'use server';

import { revalidateTag } from 'next/cache';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  if (!title || !content) {
    return { error: 'Title and content are required' };
  }

  // In a real application, you would save the post to a database here
  // For example:
  // await db.posts.create({ data: { title, content } });

  // Invalidate the posts cache tag so the next page load fetches fresh data
  // revalidateTag performs synchronous cache invalidation, ensuring no stale content is served
  revalidateTag('posts');

  return { success: true };
}

